#!/bin/bash
# AI DISCLAIMER: All of the text in this file was generated by AI.
# G019 W kit: monerod start-up from a dropped page cache, stock (A) against the index warm-up commits (W).
# usage: PEER=.. PEER_RPC=.. DD=.. SNAP=.. wk_run.sh <outdir> <END> <TIMEOUT s> <order, e.g. "A W W A A W W A">
# Per run: fresh copy of the snapshot, sync, drop the page cache, launch; rpc_s = launch to the first get_height answer
# (polled every 0.1 s); end_s = launch to the log's "Synced END"; cpu_s over the run; the warm-up's own log lines;
# the top hash against the peer's at the same height after the run (offline restart). Marker: last line WK_DONE <rc>.
set -u
OUT=$1; END=$2; TO=$3; ORDER=$4; BIN=$HOME/work/pc/bin
P2P_PORT=38080; RPC_PORT=38081
mkdir -p "$OUT"; S=$OUT/summary.txt; R=$OUT/results.csv
echo "wk start $(date -u +%FT%TZ) end=$END order=[$ORDER]" > "$S"
for a in $(echo $ORDER | tr ' ' '\n' | sort -u); do echo "arm $a $(sha256sum $BIN/$a/monerod | cut -c1-16)" >> "$S"; done
echo "run,arm,start_h,rpc_s,end_s,cpu_s,read_MB,tip_h,hash_match" > "$R"
CUR=; trap '[ -n "$CUR" ] && kill -TERM $CUR 2>/dev/null' EXIT
G0=$(cat /sys/devices/system/cpu/cpu0/cpufreq/scaling_governor); sudo -n cpupower -c all frequency-set -g performance >/dev/null 2>&1
busy() { ss -ltn | awk 'NR>1{print $4}' | grep -qE "[:.]$1\$"; }
stopn() { curl -s -m 30 http://127.0.0.1:$RPC_PORT/stop_daemon -d '{}' >/dev/null; for i in $(seq 1 120); do kill -0 $1 2>/dev/null || { CUR=; return; }; sleep 1; done; kill -TERM $1; sleep 30; kill -KILL $1 2>/dev/null; CUR=; }
n=0
for A in $ORDER; do
  n=$((n+1)); tag=w${n}_$A; LOG=$OUT/$tag.log
  for p in $P2P_PORT $RPC_PORT; do busy $p && { echo "REFUSE port $p busy" >> "$S"; exit 3; }; done
  case "$DD" in */wkdd) ;; *) echo "REFUSE DD must end in /wkdd" >> "$S"; exit 3;; esac
  rm -rf "$DD"; mkdir -p "$DD/testnet/lmdb"; cp -- "$SNAP/testnet/lmdb/data.mdb" "$DD/testnet/lmdb/data.mdb" || exit 3
  sync; echo 3 | sudo -n tee /proc/sys/vm/drop_caches >/dev/null
  echo "[$tag] start $(date -u +%FT%TZ) load $(cut -d' ' -f1-3 /proc/loadavg) other_monerod $(ps -eo comm= | grep -c '^monerod$')" >> "$S"
  t0=$(date +%s.%N)
  $BIN/$A/monerod --testnet --data-dir "$DD" --add-exclusive-node "$PEER" --p2p-bind-ip 127.0.0.1 --p2p-bind-port $P2P_PORT \
    --rpc-bind-ip 127.0.0.1 --rpc-bind-port $RPC_PORT --no-zmq --no-igd --non-interactive --disable-dns-checkpoints \
    --check-updates disabled --log-file "$LOG" --log-level 0 > $OUT/$tag.stdout 2>&1 &
  MP=$!; CUR=$MP; rpc=na; h0=
  while kill -0 $MP 2>/dev/null; do
    r=$(curl -s -m 2 http://127.0.0.1:$RPC_PORT/get_height 2>/dev/null)
    if echo "$r" | grep -q '"height"'; then rpc=$(awk -v a=$t0 -v b=$(date +%s.%N) 'BEGIN{printf "%.2f", b-a}'); h0=$(echo "$r" | grep -oE '"height": [0-9]+' | grep -oE '[0-9]+$'); break; fi
    sleep 0.1
  done
  e=na
  while kill -0 $MP 2>/dev/null; do
    h=$(grep -oE "Synced [0-9]+/" "$LOG" | tail -1 | grep -oE "[0-9]+"); h=${h:-0}
    [ "$h" -ge "$END" ] && { e=$(awk -v a=$t0 -v b=$(date +%s.%N) 'BEGIN{printf "%.1f", b-a}'); break; }
    awk -v a=$t0 -v b=$(date +%s) -v t=$TO 'BEGIN{exit !(b-a>=t)}' && break
    sleep 0.5
  done
  cpu=$(awk -v hz=$(getconf CLK_TCK) '{printf "%.1f", ($14+$15)/hz}' /proc/$MP/stat 2>/dev/null)
  rd=$(awk '/^read_bytes/{print int($2/1048576)}' /proc/$MP/io 2>/dev/null)
  stopn $MP
  grep -iE "warm" "$LOG" | head -5 | sed "s/^/[$tag] /" >> "$S"
  "$BIN/$A/monerod" --testnet --data-dir "$DD" --offline --non-interactive --no-igd --no-zmq --disable-dns-checkpoints --check-updates disabled \
    --p2p-bind-ip 127.0.0.1 --p2p-bind-port $P2P_PORT --rpc-bind-ip 127.0.0.1 --rpc-bind-port $RPC_PORT --log-file $OUT/check.log --log-level 0 >/dev/null 2>&1 &
  CP=$!; CUR=$CP; for i in $(seq 1 120); do curl -s -m 2 http://127.0.0.1:$RPC_PORT/get_height | grep -q height && break; sleep 1; done
  q=$(curl -s -m 30 http://127.0.0.1:$RPC_PORT/json_rpc -d '{"jsonrpc":"2.0","id":0,"method":"get_last_block_header"}')
  ti=$(echo "$q" | grep -oE '"height": [0-9]+' | head -1 | grep -oE '[0-9]+$'); ours=$(echo "$q" | grep -oE '"hash": "[0-9a-f]+"' | head -1 | cut -d'"' -f4)
  theirs=$(curl -s -m 30 http://$PEER_RPC/json_rpc -d "{\"jsonrpc\":\"2.0\",\"id\":0,\"method\":\"get_block_header_by_height\",\"params\":{\"height\":${ti:-0}}}" | grep -oE '"hash": "[0-9a-f]+"' | head -1 | cut -d'"' -f4)
  stopn $CP
  m=NO; [ -n "$ours" ] && [ "$ours" = "$theirs" ] && m=yes
  echo "$tag,$A,$h0,$rpc,$e,$cpu,$rd,$ti,$m" >> "$R"
  echo "[$tag] rpc_s $rpc end_s $e cpu_s $cpu read_MB $rd tip $ti hash $m errors $(grep -c ERROR $LOG)" >> "$S"
done
rm -rf "$DD"
sudo -n cpupower -c all frequency-set -g $G0 >/dev/null 2>&1
echo "$(date -u +%FT%TZ) WK_DONE 0" >> "$S"
